@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class FortressArmorAudit {
 static int ticks,started;static volatile int completed;static volatile boolean ready,done;static final BlockPos POS=InfusionAudit.POS;static ItemStack helmet;static final List<String> RECIPES=List.of("ThaumiumFortressHelm","ThaumiumFortressChest","ThaumiumFortressLegs","HelmGoggles","MaskGrinningDevil","MaskAngryGhost","MaskSippingFiend");
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_FORTRESS FAIL "+s);System.out.println("TC4_FORTRESS PASS "+s);}
 static void prepare(ServerPlayer p){p.getInventory().selected=0;for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)p.serverLevel().setBlock(POS.offset(x,-4,z),Blocks.AIR.defaultBlockState(),2);InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;RunicAudit.clear(p);var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);for(var piece:List.of("helmet","chestplate","leggings")){var stack=new ItemStack(FortressArmor.item(piece));check(stack.getItem() instanceof FortressArmor.Piece,"registered "+piece);check(((ArmorItem)stack.getItem()).isValidRepairItem(stack,new ItemStack(ThaumiumContent.ingot())),"thaumium repair "+piece);p.setItemSlot(switch(piece){case "helmet"->EquipmentSlot.HEAD;case "chestplate"->EquipmentSlot.CHEST;default->EquipmentSlot.LEGS;},stack);}p.doTick();
  check(p.getItemBySlot(EquipmentSlot.HEAD).getMaxDamage()==440&&p.getItemBySlot(EquipmentSlot.CHEST).getMaxDamage()==640&&p.getItemBySlot(EquipmentSlot.LEGS).getMaxDamage()==600,"original durability440/640/600");
  check(Math.abs(FortressArmor.multiplier(p)-1.25)<1e-6,"threepiece multiplier1.25");var head=p.getItemBySlot(EquipmentSlot.HEAD);var tag=NoteData.tag(head);tag.putInt("mask",2);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));check(Math.abs(FortressArmor.multiplier(p)-1.3)<1e-6,"mask multiplier1.30");
  float regular=FortressArmor.absorb(p,l.damageSources().mobAttack(new net.minecraft.world.entity.monster.Zombie(l)),10);check(Math.abs(regular-1.68)<.001,"legacy regular ratio leaves1.68 of10");p.invulnerableTime=0;p.setHealth(20);p.hurt(l.damageSources().magic(),10);check(Math.abs(p.getHealth()-(20-(10-16*1.3/35*10)))<.001,"real hurt uses legacy armor mixin on magic");p.setHealth(20);p.invulnerableTime=0;float magic=FortressArmor.absorb(p,l.damageSources().magic(),10);check(Math.abs(magic-(10-16*1.3/35*10))<.001,"magic priority protects bypassarmor");float fire=FortressArmor.absorb(p,l.damageSources().inFire(),10);check(fire<.001,"fire ratio normalization fullyabsorbs");int damage=head.getDamageValue();FortressArmor.absorb(p,l.damageSources().fall(),10);check(head.getDamageValue()==damage,"fall neverdamages fortress");
  for(var stack:p.getArmorSlots())if(!stack.isEmpty())stack.setDamageValue(stack.getMaxDamage()-1);check(FortressArmor.absorb(p,l.damageSources().magic(),10)>9.7,"remainingdurability caps absorption");for(var piece:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS))p.setItemSlot(piece,new ItemStack(FortressArmor.item(piece==EquipmentSlot.HEAD?"helmet":piece==EquipmentSlot.CHEST?"chestplate":"leggings")));
  var zombie=new net.minecraft.world.entity.monster.Zombie(l);zombie.setPos(p.getX()+2,p.getY(),p.getZ());zombie.setNoAi(true);l.addFreshEntity(zombie);head=p.getItemBySlot(EquipmentSlot.HEAD);tag=NoteData.tag(head);tag.putInt("mask",1);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var incoming=new net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent(p,new net.neoforged.neoforge.common.damagesource.DamageContainer(l.damageSources().mobAttack(zombie),10));FortressArmor.masks(incoming);check(zombie.hasEffect(net.minecraft.world.effect.MobEffects.WITHER)&&zombie.getEffect(net.minecraft.world.effect.MobEffects.WITHER).getDuration()==80,"angrymask actual incoming event wither80");tag.putInt("mask",2);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));p.setHealth(10);var outgoing=new net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent(zombie,new net.neoforged.neoforge.common.damagesource.DamageContainer(l.damageSources().playerAttack(p),12));FortressArmor.masks(outgoing);check(p.getHealth()==11,"sippingmask actual outgoing event heals1");zombie.removeAllEffects();p.getPersistentData().putInt("TC4RunicCharge",10);tag.putInt("mask",1);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var shielded=new net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent(p,new net.neoforged.neoforge.common.damagesource.DamageContainer(l.damageSources().mobAttack(zombie),10));net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(shielded);check(shielded.getAmount()==0&&zombie.hasEffect(net.minecraft.world.effect.MobEffects.WITHER),"mask triggers BEFORE actual runic event absorption");p.getPersistentData().putInt("TC4RunicCharge",0);RunicRingShield.rechargeDelay=0;tag.putInt("mask",2);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));p.setHealth(10);zombie.hurt(l.damageSources().playerAttack(p),12);check(p.getHealth()==11,"real hurt dispatch heals owner");zombie.discard();p.setHealth(p.getMaxHealth());
  FortressArmor.withGoggles(head);check(((FortressArmor.Piece)head.getItem()).showNodes(head,p)&&((FortressArmor.Piece)head.getItem()).showIngamePopups(head,p),"goggles revealer andHUD interfaces");
  tag=NoteData.tag(head);tag.putInt("mask",0);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var oldWarp=PlayerWarp.load(p);var warp=new WarpState();warp.set(WarpState.Kind.PERMANENT,50);warp.setCounter(100);PlayerWarp.save(p,warp);var playerRoll=WarpEventRoll.check(p,0,n->0);check(playerRoll.effect()==-2,"real equipped grinningmask reduces event roll");PlayerWarp.save(p,oldWarp);tag.putInt("mask",2);head.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var a=WarpEventRoll.check(50,0,0,100,0,false,n->0);var b=WarpEventRoll.check(50,0,0,100,0,true,n->0);check(b.effect()==a.effect()-2,"grinningmask reduces warp effect original2..5");
  for(var key:RECIPES){var r=ElementalToolsAudit.recipe(key);var center=new ItemStack(r.central().get());check(!center.isEmpty()&&r.componentStacks().stream().noneMatch(ItemStack::isEmpty),"alloriginal ingredients registered "+key);check(InfusionItemRecipes.match(r.componentStacks(),center,Set.of(r.research()))==r&&InfusionItemRecipes.match(r.componentStacks(),center,Set.of())==null,"exact recipe and researchgate "+key);}
  p.connection.teleport(POS.getX()+6,POS.getY()+1,POS.getZ()-7,40,15);for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)if(x!=0||z!=0){l.setBlock(POS.offset(x,-5,z),Blocks.STONE.defaultBlockState(),2);l.setBlock(POS.offset(x,-4,z),Blocks.SKELETON_SKULL.defaultBlockState(),2);}if(Boolean.getBoolean("tc4modern.fortressMasksAuditOnly")){completed=4;helmet=FortressArmor.withGoggles(new ItemStack(FortressArmor.item("helmet")));helmet.setDamageValue(17);helmet.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.UNBREAKING),2);}ready=true;if(!Boolean.getBoolean("tc4modern.fortressQuickAuditOnly"))start(p);
 }
 static void start(ServerPlayer p){var l=p.serverLevel();var r=ElementalToolsAudit.recipe(RECIPES.get(completed));var central=r.augment()?helmet.copy():new ItemStack(r.central().get());if(r.key().equals("HelmGoggles")){central.setDamageValue(17);central.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.UNBREAKING),2);}((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(central);for(var at:ArcaneBoreAudit.PEDS)l.setBlock(at,Blocks.AIR.defaultBlockState(),3);for(var at:TravellerBootsAudit.PEDESTALS)l.setBlock(at,Blocks.AIR.defaultBlockState(),3);for(int i=0;i<r.components().size();i++){var at=ArcaneBoreAudit.PEDS.get(i);l.setBlock(at,InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(at)).setItem(r.componentStacks().get(i));}for(int x=-8;x<=8;x++)l.setBlock(POS.offset(x,-2,-4),Blocks.AIR.defaultBlockState(),3);int i=0;for(var a:r.aspects().getAspects()){var at=POS.offset(i++*2-4,-2,-4);l.setBlock(at,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(at);jar.state.aspect=a;jar.state.amount=r.aspects().getAmount(a);jar.changed();}l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(POS).inflate(30)).forEach(Entity::discard);InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==r.aspects().visSize(),"natural altar starts "+r.key());System.out.println("TC4_FORTRESS STABILITY "+InfusionAudit.matrix.logic.symmetry+" instability="+InfusionAudit.matrix.logic.instability);check(InfusionAudit.matrix.logic.instability<=0,"sufficient real stabilizers "+r.key());started=ticks;}
 static void advance(ServerPlayer p){if(done||Boolean.getBoolean("tc4modern.fortressQuickAuditOnly"))return;if(InfusionAudit.matrix.logic.crafting){if(ticks-started>=3000)throw new IllegalStateException("altar stalled "+RECIPES.get(completed)+" essentia="+InfusionAudit.matrix.logic.recipeEssentia+" remaining="+InfusionAudit.matrix.logic.recipeIngredients);return;}var r=ElementalToolsAudit.recipe(RECIPES.get(completed));var l=p.serverLevel();var output=((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item();check(output.is(r.output().get()),"natural altar output "+r.key());for(int i=0;i<r.components().size();i++)check(ItemStack.isSameItemSameComponents(((InfusionContent.PedestalEntity)l.getBlockEntity(ArcaneBoreAudit.PEDS.get(i))).item(),r.componentStacks().get(i).getCraftingRemainingItem()),"consumedcomponent and correct container "+r.key()+"/"+i);for(int i=0;i<r.aspects().size();i++)check(((WardedJarEntity)l.getBlockEntity(POS.offset(i*2-4,-2,-4))).state.amount==0,"exactessentia "+r.key()+"/"+i);if(r.key().equals("ThaumiumFortressHelm")||r.augment())helmet=output.copy();if(r.augment()){check(output.getDamageValue()==17&&BasicsEnchantments.level(p,output,Enchantments.UNBREAKING)==2,"preservesdamage+enchants "+r.key());check(NoteData.tag(output).contains("goggles"),"preservesgoggles "+r.key());if(r.key().startsWith("Mask"))check(NoteData.tag(output).getInt("mask")==completed-4,"exactmask index "+r.key());}completed++;if(completed==7){done=true;System.out.println("TC4_FORTRESS ALL SEVEN NATURAL INFUSIONS PASS");}else start(p);}
 static final List<String> BOOK=List.of("ARMORFORTRESS","ARMORFORTRESS","ARMORFORTRESS","HELMGOGGLES","MASKGRINNINGDEVIL","MASKANGRYGHOST","MASKSIPPINGFIEND");
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.fortressAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==140){check(ready,"server mechanics ready");mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_FRONT);}if(ticks==160){check(FortressArmorClient.rendered>0,"original armor model rendered");var cached=FortressArmorClient.CACHE.get(mc.player);check(cached!=null&&cached[0]==3&&cached[1]==2&&cached[2]==1,"actual client fullset mask andgoggles cache");LiquidDeathAudit.shot(mc,"fortress-full-set-mask-goggles.png");mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);}if(ticks>=180&&ticks<320&&(ticks-180)%20==0){int i=(ticks-180)/20;var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(BOOK.get(i)),i<3?i*2:0);mc.setScreen(book);}if(ticks>=185&&ticks<320&&(ticks-185)%20==0)LiquidDeathAudit.shot(mc,"fortress-book-"+(ticks-185)/20+".png");if(ticks==325){mc.setScreen(null);if(Boolean.getBoolean("tc4modern.fortressQuickAuditOnly")){mc.stop();return;}}if(ready&&ticks>340&&ticks%20==0)server.execute(()->advance(server.getPlayerList().getPlayer(id)));if(done&&ticks%20==10){check(completed==7,"seven recipes completed");LiquidDeathAudit.shot(mc,"fortress-seven-infusions-finished.png");mc.stop();}if(ticks>18000)throw new IllegalStateException("fortress audit timeout");}
}
